<?php $title='Paiements & caisse'; $subtitle='Suivez les encaissements et les soldes de vos abonnements.'; $section='payments'; require __DIR__.'/management_header.php'; ?>
<?php if ($canWrite): ?><details class="card form-card" <?= $error ? 'open' : '' ?>><summary>+ Enregistrer un paiement</summary><form method="post" action="payments" class="form-grid"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><label>Abonnement avec solde *<select name="subscription_id" required><option value="">Sélectionner un abonnement</option><?php foreach ($subscriptions as $s): if ($s['price']===null) continue; ?><option value="<?= (int)$s['id'] ?>" <?= (string)($s['id']) === ($_POST['subscription_id'] ?? '') ? 'selected' : '' ?>><?= e($s['first_name'].' '.$s['last_name'].' · '.$s['name'].' #'.$s['id'].' · Reste '.dt((float)$s['price']-(float)$s['paid'])) ?></option><?php endforeach; ?></select></label><label>Montant (DT) *<input name="amount" type="number" min="0.001" max="9999999" step="0.001" value="<?= e($_POST['amount'] ?? '') ?>" required></label><label>Moyen de paiement *<select name="method" required><?php foreach (['espèces','chèque','virement','D17','Flouci','carte bancaire'] as $method): ?><option value="<?= e($method) ?>" <?= ($_POST['method'] ?? '') === $method ? 'selected' : '' ?>><?= e(ucfirst($method)) ?></option><?php endforeach; ?></select></label><p class="form-hint">Le montant ne peut pas dépasser le solde au prix fixé pour l’abonnement, après déduction des remboursements. Les anciens abonnements sans prix vérifié ne peuvent pas être encaissés. L'encaissement est daté au moment de son enregistrement.</p><div class="form-actions"><button class="primary">Enregistrer le paiement</button></div></form></details><?php endif; ?>
<section class="card management-table"><div class="card-head"><div><h3>Caisse journalière</h3><p>Encaissements bruts du <?= e(date('d/m/Y',strtotime($date))) ?></p></div><strong class="cash-total"><?= e(dt($totalDay)) ?></strong></div><form action="payments" class="search-form" method="get"><label for="cash-date">Date</label><input id="cash-date" type="date" name="date" value="<?= e($date) ?>"><button class="primary">Afficher</button></form><p class="form-hint">Remboursements du jour : <?= e(dt($refundDay)) ?> · Encaissements nets : <?= e(dt((float)$totalDay-(float)$refundDay)) ?>. Les remboursements sont comptabilisés à leur date. La répartition par moyen ci-dessous indique les encaissements bruts uniquement.</p><div class="cash-methods"><?php foreach ($byMethod as $item): ?><div><span><?= e(ucfirst($item['method'])) ?> · <?= (int)$item['count'] ?></span><strong><?= e(dt($item['total'])) ?></strong></div><?php endforeach; ?><?php if (!$byMethod): ?><p class="empty">Aucun encaissement pour cette date.</p><?php endif; ?></div><div class="table-scroll"><table><thead><tr><th>HEURE</th><th>MEMBRE</th><th>ABONNEMENT</th><th>MOYEN</th><th>MONTANT</th><th>REÇU</th></tr></thead><tbody><?php foreach ($payments as $pay): ?><tr><td><?= e(date('H:i',strtotime($pay['paid_at']))) ?></td><td><strong><?= e($pay['first_name'].' '.$pay['last_name']) ?></strong></td><td><?= e($pay['plan'] ?: '—') ?></td><td><?= e(ucfirst($pay['method'])) ?></td><td><?= e(dt($pay['amount'])) ?></td><td><a class="text-link" href="receipt?id=<?= (int)$pay['id'] ?>">Voir le reçu</a></td></tr><?php endforeach; ?><?php if (!$payments): ?><tr><td colspan="6" class="empty">Aucun paiement enregistré.</td></tr><?php endif; ?></tbody></table></div><div class="pagination"><?php if ($pageNumber>1): ?><a href="payments?date=<?= e($date) ?>&amp;p=<?= $pageNumber-1 ?>">← Précédent</a><?php endif; ?><span>Page <?= $pageNumber ?> / <?= max(1,(int)ceil($total/10)) ?></span><?php if ($pageNumber*10<$total): ?><a href="payments?date=<?= e($date) ?>&amp;p=<?= $pageNumber+1 ?>">Suivant →</a><?php endif; ?></div></section>
<section class="card management-table"><div class="card-head"><div><h3>Remboursements du jour</h3><p>100 derniers enregistrements · les sommes ci-dessus incluent tous les remboursements du jour.</p></div></div><div class="table-scroll"><table><thead><tr><th>HEURE</th><th>MEMBRE</th><th>PAIEMENT</th><th>MOYEN D’ORIGINE</th><th>MONTANT</th><th>MOTIF</th></tr></thead><tbody><?php foreach ($refunds as $refund): ?><tr><td><?= e(date('H:i',strtotime($refund['refunded_at']))) ?></td><td><?= e($refund['first_name'].' '.$refund['last_name']) ?></td><td><a class="text-link" href="receipt?id=<?= (int)$refund['payment_id'] ?>">#<?= (int)$refund['payment_id'] ?></a></td><td><?= e($refund['method']) ?></td><td><?= e(dt($refund['amount'])) ?></td><td><?= e($refund['reason']) ?></td></tr><?php endforeach; ?><?php if (!$refunds): ?><tr><td colspan="6" class="empty">Aucun remboursement enregistré ce jour.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="card management-table"><div class="card-head"><div><h3>Soldes à encaisser</h3><p>Abonnements non soldés et anciens tarifs à vérifier</p></div></div><p class="form-hint">Les anciens prix doivent être vérifiés avant encaissement. <?php if (in_array($_SESSION['user']['role'],['Admin','Gérant'],true)): ?><a class="text-link" href="subscription_prices">Vérifier les prix historiques →</a><?php else: ?>Contactez un Admin ou Gérant pour les vérifier.<?php endif; ?></p><div class="table-scroll"><table><thead><tr><th>MEMBRE</th><th>FORMULE</th><th>PRIX</th><th>PAYÉ</th><th>RESTE</th></tr></thead><tbody><?php foreach ($subscriptions as $s): ?><tr><td><?= e($s['first_name'].' '.$s['last_name']) ?></td><td><?= e($s['name'].' #'.$s['id']) ?></td><td><?= $s['price']===null ? 'À vérifier' : e(dt($s['price'])) ?></td><td><?= e(dt($s['paid'])) ?></td><td><?= $s['price']===null ? 'Indéterminé' : e(dt((float)$s['price']-(float)$s['paid'])) ?></td></tr><?php endforeach; ?><?php if (!$subscriptions): ?><tr><td colspan="5" class="empty">Aucun solde en attente.</td></tr><?php endif; ?></tbody></table></div></section><?php require __DIR__.'/management_footer.php'; ?>
